<script setup lang="ts">
import type { Credential, Category } from '~~/shared/types/vault'
import { generatePassword, safeUrl } from '~~/shared/utils/crypto'
const props = defineProps<{ embedded?: boolean; mode?: string }>()
const vault = useVaultStore(), auth = useAuthStore(), toast = useToast()
const active = ref('all'), query = ref(''), sort = ref('updated'), mobileOpen = ref(false)
const entryOpen = ref(false), categoryOpen = ref(false), deleteOpen = ref(false), showPassword = ref(false)
const deleting = ref<Credential | Category | null>(null), deletingCategory = ref(false), formError = ref('')
const blankEntry = (): Credential => ({ id: '', title: '', url: '', username: '', password: '', notes: '', categoryId: '', favorite: false, createdAt: '', updatedAt: '' })
const form = reactive<Credential>(blankEntry())
const categoryForm = reactive<Category>({ id: '', name: '', icon: 'i-lucide-folder', color: '#6366f1' })
const colors = ['#6366f1', '#10b981', '#f59e0b', '#ec4899', '#0ea5e9', '#8b5cf6']
const icons = ['i-lucide-folder', 'i-lucide-briefcase-business', 'i-lucide-user-round', 'i-lucide-landmark', 'i-lucide-app-window', 'i-lucide-globe', 'i-lucide-gamepad-2', 'i-lucide-shopping-bag']
const categoryOptions = computed(() => [{ label: 'Без категории', value: '__none' }, ...vault.data.categories.map(c => ({ label: c.name, value: c.id }))])
const selectedCategory = computed({ get: () => form.categoryId || '__none', set: value => { form.categoryId = value === '__none' ? '' : value } })
const favorites = computed(() => vault.data.entries.filter(e => e.favorite).length)
const category = (id: string) => vault.data.categories.find(c => c.id === id)
const title = computed(() => active.value === 'all' ? 'Все пароли' : active.value === 'favorites' ? 'Избранное' : category(active.value)?.name ?? 'Все пароли')
const filtered = computed(() => vault.data.entries.filter(e => (active.value === 'all' || (active.value === 'favorites' ? e.favorite : e.categoryId === active.value)) && [e.title, e.username, e.url, e.notes].some(v => v.toLowerCase().includes(query.value.toLowerCase()))).sort((a, b) => sort.value === 'title' ? a.title.localeCompare(b.title, 'ru') : b.updatedAt.localeCompare(a.updatedAt)))
const categoryMode = computed(() => props.mode === 'categories')
const copyData = () => JSON.parse(JSON.stringify(vault.data))
function editEntry(entry?: Credential) { Object.assign(form, entry ?? { ...blankEntry(), categoryId: category(active.value)?.id ?? '' }); showPassword.value = false; formError.value = ''; entryOpen.value = true }
function editCategory(value?: Category) { Object.assign(categoryForm, value ?? { id: '', name: '', icon: 'i-lucide-folder', color: '#6366f1' }); formError.value = ''; categoryOpen.value = true }
function select(id: string) { active.value = id; mobileOpen.value = false }
async function saveEntry() {
  formError.value = ''
  if (!form.title.trim() || !form.password) { formError.value = 'Укажите название и пароль'; return }
  if (form.url && !safeUrl(form.url)) { formError.value = 'Укажите корректный HTTP или HTTPS адрес'; return }
  const next = copyData(), now = new Date().toISOString()
  const entry = { ...form, title: form.title.trim(), url: form.url ? safeUrl(form.url)! : '', id: form.id || crypto.randomUUID(), createdAt: form.createdAt || now, updatedAt: now }
  const index = next.entries.findIndex((e: Credential) => e.id === entry.id)
  if (index >= 0) next.entries[index] = entry; else next.entries.push(entry)
  if (await vault.save(next)) { entryOpen.value = false; Object.assign(form, blankEntry()); toast.add({ title: 'Карточка сохранена', icon: 'i-lucide-check', color: 'success' }) }
}
async function saveCategory() {
  if (!categoryForm.name.trim()) return
  if (vault.data.categories.some(c => c.id !== categoryForm.id && c.name.toLowerCase() === categoryForm.name.trim().toLowerCase())) { formError.value = 'Категория с таким названием уже существует'; return }
  const next = copyData(), value = { ...categoryForm, id: categoryForm.id || crypto.randomUUID(), name: categoryForm.name.trim() }
  const index = next.categories.findIndex((c: Category) => c.id === value.id)
  if (index >= 0) next.categories[index] = value; else next.categories.push(value)
  if (await vault.save(next)) { categoryOpen.value = false; toast.add({ title: 'Категория сохранена', color: 'success' }) }
}
async function favorite(entry: Credential) { const next = copyData(); const value = next.entries.find((e: Credential) => e.id === entry.id); value.favorite = !value.favorite; await vault.save(next) }
function askDelete(value: Credential | Category, isCategory = false) { deleting.value = value; deletingCategory.value = isCategory; deleteOpen.value = true }
async function remove() {
  if (!deleting.value) return
  const next = copyData()
  if (deletingCategory.value) { next.categories = next.categories.filter((c: Category) => c.id !== deleting.value!.id); next.entries.forEach((e: Credential) => { if (e.categoryId === deleting.value!.id) e.categoryId = '' }) }
  else next.entries = next.entries.filter((e: Credential) => e.id !== deleting.value!.id)
  if (await vault.save(next)) { if (active.value === deleting.value.id) active.value = 'all'; deleteOpen.value = false; deleting.value = null }
}
async function copy(value: string) {
  try { await navigator.clipboard.writeText(value); toast.add({ title: 'Скопировано в буфер обмена', description: 'История буфера обмена управляется вашей системой.', icon: 'i-lucide-copy', color: 'success' }) }
  catch { toast.add({ title: 'Браузер не разрешил копирование', color: 'error' }) }
}
function host(url: string) { try { return new URL(url).hostname.replace(/^www\./, '') } catch { return 'Приложение или сервис' } }
watch(() => vault.unlocked, value => { if (!value) { entryOpen.value = false; categoryOpen.value = false; deleteOpen.value = false; Object.assign(form, blankEntry()); query.value = ''; deleting.value = null; Object.assign(categoryForm, { id: '', name: '', icon: 'i-lucide-folder', color: '#6366f1' }) } })
onBeforeUnmount(() => Object.assign(form, blankEntry()))
</script>
<template>
  <div :class="['vault-shell', { embedded }]">
    <aside v-if="!embedded" :class="['vault-sidebar', { 'is-open': mobileOpen }]">
      <NuxtLink to="/" class="brand"><span class="brand-icon"><UIcon name="i-lucide-shield-check" /></span><span>magnat<span class="brand-light">password</span></span></NuxtLink>
      <button class="workspace-switch" @click="select('all')"><span class="workspace-avatar">Л</span><span><strong>Личное хранилище</strong><small>Только для вас</small></span><UIcon name="i-lucide-chevrons-up-down" /></button>
      <p class="sidebar-label">ХРАНИЛИЩЕ</p>
      <nav class="vault-nav" aria-label="Хранилище">
        <button :class="{ selected: active === 'all' }" @click="select('all')"><UIcon name="i-lucide-layout-grid" />Все пароли<span>{{ vault.data.entries.length }}</span></button>
        <button :class="{ selected: active === 'favorites' }" @click="select('favorites')"><UIcon name="i-lucide-star" />Избранное<span>{{ favorites }}</span></button>
      </nav>
      <div class="sidebar-label category-label">КАТЕГОРИИ<button title="Добавить категорию" aria-label="Добавить категорию" @click="editCategory()"><UIcon name="i-lucide-plus" /></button></div>
      <nav class="vault-nav" aria-label="Категории"><button v-for="c in vault.data.categories" :key="c.id" :class="{ selected: active === c.id }" @click="select(c.id)"><UIcon :name="c.icon" :style="{ color: c.color }" />{{ c.name }}<span>{{ vault.data.entries.filter(e => e.categoryId === c.id).length }}</span></button></nav>
      <button class="add-category" @click="editCategory()"><UIcon name="i-lucide-plus" />Новая категория</button>
      <div class="sidebar-bottom"><div class="encryption-card"><span class="encryption-icon"><UIcon name="i-lucide-shield-check" /></span><strong>Под надёжной защитой</strong><p>Ваши данные зашифрованы.<br>Доступ к ним есть только у вас.</p><span class="encryption-tag"><i /> AES-256-GCM</span></div><NuxtLink to="/admin" class="sidebar-admin"><UIcon name="i-lucide-settings-2" />Панель управления<UIcon name="i-lucide-arrow-up-right" /></NuxtLink><div class="sidebar-user"><span class="user-avatar">{{ auth.user?.email?.[0]?.toUpperCase() }}</span><span><strong>Мой аккаунт</strong><small>{{ auth.user?.email }}</small></span><button title="Выйти" aria-label="Выйти" @click="auth.logout()"><UIcon name="i-lucide-log-out" /></button></div></div>
    </aside>
    <button v-if="mobileOpen" class="sidebar-scrim" aria-label="Закрыть меню" @click="mobileOpen = false" />
    <main class="vault-main">
      <header v-if="!embedded" class="vault-topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Открыть меню" @click="mobileOpen = !mobileOpen"><UIcon name="i-lucide-menu" /></button><UIcon name="i-lucide-house" /><span>Личное хранилище</span><UIcon name="i-lucide-chevron-right" /><strong>{{ title }}</strong></div><div class="topbar-actions"><span class="secure-status"><i />Хранилище открыто</span><UButton color="neutral" variant="ghost" icon="i-lucide-download" aria-label="Скачать зашифрованную резервную копию" title="Зашифрованная резервная копия" @click="vault.exportEncrypted()" /><UButton color="neutral" variant="ghost" icon="i-lucide-lock-keyhole" label="Заблокировать" size="sm" @click="vault.lock()" /></div></header>
      <div class="vault-content">
        <div v-if="!embedded" class="welcome-line"><span class="eyebrow">ПОРЯДОК В ЦИФРОВОЙ ЖИЗНИ</span><span class="vault-date">Ваше безопасное пространство</span></div>
        <div class="page-heading"><div><h1>{{ categoryMode ? 'Категории' : title }}<span class="title-dot">.</span></h1><p>{{ categoryMode ? 'Организуйте доступы так, как удобно вам.' : 'Все важные доступы — в одном надёжном месте.' }}</p></div><div class="heading-actions"><UButton v-if="category(active) && !categoryMode" color="neutral" variant="outline" icon="i-lucide-pencil" aria-label="Изменить категорию" @click="editCategory(category(active))" /><UButton v-if="category(active) && !categoryMode" color="neutral" variant="outline" icon="i-lucide-trash-2" aria-label="Удалить категорию" @click="askDelete(category(active)!, true)" /><UButton size="lg" icon="i-lucide-plus" :label="categoryMode ? 'Новая категория' : 'Добавить пароль'" @click="categoryMode ? editCategory() : editEntry()" /></div></div>
        <div v-if="!embedded" class="stats-grid"><div class="stat"><span class="stat-icon violet"><UIcon name="i-lucide-key-round" /></span><div><small>Всего паролей</small><strong>{{ vault.data.entries.length.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">В вашем хранилище</span></div><div class="stat"><span class="stat-icon amber"><UIcon name="i-lucide-star" /></span><div><small>В избранном</small><strong>{{ favorites.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">Всегда под рукой</span></div><div class="stat"><span class="stat-icon green"><UIcon name="i-lucide-folders" /></span><div><small>Категорий</small><strong>{{ vault.data.categories.length.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">Всё на своих местах</span></div></div>
        <UAlert v-if="vault.error" class="mb-5" color="error" variant="soft" :description="vault.error" />
        <template v-if="categoryMode"><div class="category-grid"><article v-for="c in vault.data.categories" :key="c.id" class="category-tile"><span class="category-icon" :style="{ color: c.color, background: `${c.color}12` }"><UIcon :name="c.icon" /></span><div><h3>{{ c.name }}</h3><p>{{ vault.data.entries.filter(e => e.categoryId === c.id).length }} записей</p></div><UButton color="neutral" variant="ghost" icon="i-lucide-pencil" aria-label="Изменить" @click="editCategory(c)" /><UButton color="neutral" variant="ghost" icon="i-lucide-trash-2" aria-label="Удалить" @click="askDelete(c, true)" /></article></div></template>
        <template v-else>
          <div class="filter-bar"><UInput v-model="query" icon="i-lucide-search" placeholder="Найти пароль, сайт или логин…" aria-label="Поиск по хранилищу" size="lg" class="vault-search" /><div class="filter-right"><span>{{ filtered.length }} записей</span><USelect v-model="sort" :items="[{ label: 'Сначала новые', value: 'updated' }, { label: 'По названию', value: 'title' }]" aria-label="Сортировка" size="lg" /></div></div>
          <div v-if="filtered.length" class="credential-grid"><article v-for="entry in filtered" :key="entry.id" class="credential-card"><div class="credential-card-top"><span class="service-avatar" :style="{ color: category(entry.categoryId)?.color || '#64748b', background: `${category(entry.categoryId)?.color || '#64748b'}12` }">{{ entry.title.slice(0, 1).toUpperCase() }}</span><button :class="['favorite-button', { 'is-favorite': entry.favorite }]" :aria-label="entry.favorite ? 'Убрать из избранного' : 'В избранное'" :disabled="vault.busy" @click="favorite(entry)"><UIcon name="i-lucide-star" /></button></div><button class="credential-title" @click="editEntry(entry)">{{ entry.title }}</button><a v-if="safeUrl(entry.url)" :href="safeUrl(entry.url)" target="_blank" rel="noopener noreferrer" class="credential-domain">{{ host(entry.url) }}<UIcon name="i-lucide-arrow-up-right" /></a><span v-else class="credential-domain">Приложение или сервис</span><div class="credential-fields"><div><span>Логин</span><strong>{{ entry.username || 'Не указан' }}</strong><button :disabled="!entry.username" aria-label="Скопировать логин" @click="copy(entry.username)"><UIcon name="i-lucide-copy" /></button></div><div><span>Пароль</span><strong class="password-dots">••••••••••••</strong><button aria-label="Скопировать пароль" @click="copy(entry.password)"><UIcon name="i-lucide-copy" /></button></div></div><div class="credential-footer"><span class="category-badge"><i :style="{ background: category(entry.categoryId)?.color || '#94a3b8' }" />{{ category(entry.categoryId)?.name || 'Без категории' }}</span><div><button aria-label="Изменить карточку" @click="editEntry(entry)"><UIcon name="i-lucide-pencil" /></button><button aria-label="Удалить карточку" @click="askDelete(entry)"><UIcon name="i-lucide-trash-2" /></button></div></div></article><button class="new-card" @click="editEntry()"><span><UIcon name="i-lucide-plus" /></span><strong>Ещё один пароль</strong><p>Пусть всё будет под рукой</p></button></div>
          <div v-else class="empty-vault"><div class="empty-illustration"><div class="orbit orbit-one" /><div class="orbit orbit-two" /><span class="floating-key"><UIcon name="i-lucide-key-round" /></span><span class="empty-lock"><UIcon name="i-lucide-lock-keyhole" /></span><span class="floating-check"><UIcon name="i-lucide-check" /></span></div><span class="eyebrow">{{ query ? 'ПОИСК ПО ХРАНИЛИЩУ' : 'НАЧНИТЕ С ПЕРВОГО СЕКРЕТА' }}</span><h2>{{ query ? 'Ничего не нашлось' : active === 'favorites' ? 'Самое важное — рядом' : 'Здесь будут ваши пароли' }}</h2><p>{{ query ? 'Попробуйте другое название, логин или адрес сайта.' : active === 'favorites' ? 'Нажмите на звёздочку в карточке, чтобы добавить её в избранное.' : 'Добавьте первый доступ к сайту или приложению. Мы позаботимся о порядке и защите.' }}</p><UButton v-if="!query && active !== 'favorites'" size="lg" icon="i-lucide-plus" label="Добавить первый пароль" @click="editEntry()" /><UButton v-if="query" color="neutral" variant="outline" label="Сбросить поиск" @click="query = ''" /><div class="empty-features"><span><UIcon name="i-lucide-shield-check" />Сквозное шифрование</span><span><UIcon name="i-lucide-folder" />Удобные категории</span><span><UIcon name="i-lucide-sparkles" />Генератор паролей</span></div></div>
        </template>
        <div v-if="!embedded" class="vault-tip"><span><UIcon name="i-lucide-lightbulb" /></span><p><strong>Маленькая привычка — большая защита.</strong> Используйте уникальный пароль для каждого сервиса. Генератор поможет его придумать.</p><UIcon name="i-lucide-sparkles" /></div>
        <footer v-if="!embedded" class="vault-footer"><span>Magnat Password <span class="footer-divider">/</span> Только вы знаете свои секреты.</span><span><UIcon name="i-lucide-lock-keyhole" />Автоблокировка через 5 минут бездействия</span></footer>
      </div>
    </main>
    <UModal v-model:open="entryOpen" :title="form.id ? 'Изменить пароль' : 'Новый пароль'" description="Данные будут зашифрованы перед сохранением." :dismissible="!vault.busy">
      <template #body><form id="entry-form" class="space-y-4" @submit.prevent="saveEntry"><UFormField label="Название" required><UInput v-model="form.title" placeholder="Например, Яндекс" class="w-full" required :maxlength="120" /></UFormField><UFormField label="Адрес сайта"><UInput v-model="form.url" placeholder="https://example.com" class="w-full" :maxlength="2000" /></UFormField><UFormField label="Логин или email"><UInput v-model="form.username" autocomplete="off" class="w-full" :maxlength="300" /></UFormField><UFormField label="Пароль" required><div class="flex gap-2"><UInput v-model="form.password" :type="showPassword ? 'text' : 'password'" autocomplete="off" class="flex-1" required :maxlength="1024" /><UButton color="neutral" variant="outline" :icon="showPassword ? 'i-lucide-eye-off' : 'i-lucide-eye'" aria-label="Показать или скрыть пароль" @click="showPassword = !showPassword" /><UButton color="neutral" variant="outline" icon="i-lucide-refresh-cw" aria-label="Сгенерировать пароль" @click="form.password = generatePassword(); showPassword = true" /></div><p class="mt-2 text-xs" :class="form.password.length >= 12 ? 'text-emerald-600' : 'text-amber-600'">{{ form.password.length >= 12 ? 'Хорошая длина пароля' : 'Рекомендуем не меньше 12 символов' }} · Генератор создаёт 24 символа</p></UFormField><UFormField label="Категория"><USelect v-model="selectedCategory" :items="categoryOptions" class="w-full" /></UFormField><UFormField label="Заметка"><UTextarea v-model="form.notes" class="w-full" placeholder="Дополнительная информация" :maxlength="10000" /></UFormField><UCheckbox v-model="form.favorite" label="Добавить в избранное" /><UAlert v-if="formError || vault.error" color="error" :description="formError || vault.error" /></form></template>
      <template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="outline" label="Отмена" :disabled="vault.busy" @click="entryOpen = false" /><UButton type="submit" form="entry-form" label="Сохранить пароль" :loading="vault.busy" /></div></template>
    </UModal>
    <UModal v-model:open="categoryOpen" :title="categoryForm.id ? 'Изменить категорию' : 'Новая категория'" description="Соберите похожие доступы вместе.">
      <template #body><form id="category-form" class="space-y-5" @submit.prevent="saveCategory"><UFormField label="Название" required><UInput v-model="categoryForm.name" class="w-full" placeholder="Например, Покупки" required :maxlength="60" /></UFormField><UFormField label="Цвет"><div class="flex gap-3"><button v-for="color in colors" :key="color" type="button" :aria-label="color" :aria-pressed="categoryForm.color === color" class="color-swatch" :style="{ background: color, outline: categoryForm.color === color ? `2px solid ${color}` : 'none' }" @click="categoryForm.color = color"><UIcon v-if="categoryForm.color === color" name="i-lucide-check" /></button></div></UFormField><UFormField label="Иконка"><div class="flex flex-wrap gap-2"><UButton v-for="icon in icons" :key="icon" type="button" :icon="icon" :aria-label="icon" :color="categoryForm.icon === icon ? 'primary' : 'neutral'" :variant="categoryForm.icon === icon ? 'soft' : 'outline'" @click="categoryForm.icon = icon" /></div></UFormField><UAlert v-if="formError || vault.error" color="error" :description="formError || vault.error" /></form></template><template #footer><UButton type="submit" form="category-form" label="Сохранить категорию" :loading="vault.busy" /></template>
    </UModal>
    <UModal v-model:open="deleteOpen" :title="deletingCategory ? 'Удалить категорию?' : 'Удалить пароль?'" :description="deletingCategory ? 'Карточки сохранятся и перейдут в «Без категории».' : 'Восстановить удалённую карточку будет невозможно.'"><template #body><p class="text-sm text-slate-500">{{ deleting && ('title' in deleting ? deleting.title : deleting.name) }}</p><UAlert v-if="vault.error" color="error" :description="vault.error" /></template><template #footer><UButton color="neutral" variant="outline" label="Отмена" @click="deleteOpen = false" /><UButton color="error" label="Удалить" :loading="vault.busy" @click="remove" /></template></UModal>
  </div>
</template>
